"""Exploratory analysis for the disaster-relief route task. Run: python analyze_results.py"""
import os, sqlite3
from pathlib import Path
import pandas as pd
DB_PATH=Path(os.environ.get("ROUTE_STUDY_DB","data/route_study_fixed_v21_fuel_feasible_hindsight.sqlite")); OUT=Path(os.environ.get("ROUTE_STUDY_OUTPUT","analysis_outputs")); OUT.mkdir(parents=True,exist_ok=True)
RECOMMENDED={"easy_risky_better":"risky","easy_safe_better":"safe"}
def pct(x):
 x=pd.Series(x).dropna(); return round(100*x.mean(),1) if len(x) else float("nan")
def boolean(x): return x.astype(str).str.lower().eq("true")
def write_groups(trials, group, filename):
 rows=[]
 for v,g in trials.dropna(subset=[group]).groupby(group):
  n=g.participant_id.nunique(); rows.append({group:v,"participants":n,"trials":len(g),"mean_excess_time":round(g.excess_distance.mean(),2),"realized-optimal arrivals (%)":pct(g.realized_optimal),"on-time arrivals (%)":pct(g.on_time_bool),"easy normative first choices (%)":pct(g.loc[g.difficulty.eq("easy"),"good_first_choice"]),"trials using surveillance (%)":pct(g.used_surveillance),"mean surveys per trial":round(g.surveillance_count.mean(),2),"interpretation":"descriptive only" if n<20 else "descriptive; model before inference"})
 pd.DataFrame(rows).to_csv(OUT/filename,index=False)
if not DB_PATH.exists(): raise SystemExit(f"No database found at {DB_PATH}. Run the Streamlit task first or set ROUTE_STUDY_DB.")
with sqlite3.connect(DB_PATH) as c: events=pd.read_sql_query("SELECT * FROM events",c)
if events.empty: raise SystemExit("The database contains no events.")
stranded_events=events.loc[events.event.eq("stranded")].copy()
stranded_events.to_csv(OUT/"stranded_trials.csv",index=False)
for col in ["surveilled_edge","surveillance_number","surveilled_open","survey_hindsight_relevant", "fuel_before", "fuel_after", "fuel_capacity", "refuelled"]:
 if col not in events: events[col]=pd.NA
trials=events.loc[events.event.eq("arrival")].copy()
if trials.empty: raise SystemExit("No completed trials yet. Raw/incomplete events remain in the database.")
trials["on_time_bool"]=boolean(trials.on_time); trials["realized_optimal"]=trials.excess_distance.fillna(float("inf")).eq(0)
first=(events.loc[events.event.eq("move")&events.choice_class.notna()].sort_values(["participant_id","trial","elapsed_seconds","wallclock_utc"]).drop_duplicates(["participant_id","trial"])[["participant_id","trial","choice_class"]])
trials=trials.drop(columns=["choice_class"],errors="ignore").merge(first,on=["participant_id","trial"],how="left"); trials["recommended_choice"]=trials.condition.map(RECOMMENDED); trials["good_first_choice"]=trials.choice_class.eq(trials.recommended_choice).where(trials.recommended_choice.notna()); trials["safe_on_equal_mean"]=trials.choice_class.eq("safe").where(trials.condition.eq("hard_equal_mean"))
surveys=events.loc[events.event.eq("surveillance")].copy(); arrival=trials[["participant_id","trial","elapsed_seconds","route_distance"]].rename(columns={"elapsed_seconds":"trial_decision_seconds","route_distance":"final_route_distance"}); surveys=surveys.merge(arrival,on=["participant_id","trial"],how="left")
if not surveys.empty:
 surveys["surveilled_open_bool"]=boolean(surveys.surveilled_open); surveys["hindsight_relevant_bool"]=boolean(surveys.survey_hindsight_relevant); surveys["relative_decision_time"]=surveys.elapsed_seconds/surveys.trial_decision_seconds.where(surveys.trial_decision_seconds.gt(0)); surveys["relative_route_progress"]=surveys.route_distance/surveys.final_route_distance.where(surveys.final_route_distance.gt(0)); surveys["timing_stage"]=pd.cut(surveys.relative_decision_time,[-float("inf"),1/3,2/3,float("inf")],labels=["early","middle","late"]).astype(object); surveys.loc[surveys.moves.eq(0),"timing_stage"]="before first move"; surveys.to_csv(OUT/"surveillance_events.csv",index=False)
rollup=(surveys.groupby(["participant_id","trial"]).agg(surveillance_count=("event","size"),relevant_survey_count=("hindsight_relevant_bool","sum"),blocked_survey_count=("surveilled_open_bool",lambda x:(~x).sum()),first_survey_seconds=("elapsed_seconds","min")).reset_index() if not surveys.empty else pd.DataFrame(columns=["participant_id","trial","surveillance_count","relevant_survey_count","blocked_survey_count","first_survey_seconds"]))
trials=trials.merge(rollup,on=["participant_id","trial"],how="left")
for col in ["surveillance_count","relevant_survey_count","blocked_survey_count"]: trials[col]=trials[col].fillna(0).astype(int)
trials["used_surveillance"]=trials.surveillance_count.gt(0)
fuel_moves=events.loc[events.event.eq("move")].copy()
fuel_moves["refuelled_bool"]=boolean(fuel_moves.refuelled)
refuels=fuel_moves.groupby(["participant_id","trial"]).agg(refuel_visits=("refuelled_bool","sum"), minimum_fuel_remaining=("fuel_after","min")).reset_index()
trials=trials.merge(refuels,on=["participant_id","trial"],how="left")
trials["refuel_visits"]=trials.refuel_visits.fillna(0).astype(int)
trials["all_surveys_hindsight_relevant"]=trials.relevant_survey_count.eq(trials.surveillance_count).where(trials.used_surveillance); trials.to_csv(OUT/"participant_trial_data.csv",index=False)
summary=pd.DataFrame([{ "completed_participants":trials.participant_id.nunique(),"completed_trials":len(trials),"mean_excess_travel_time":round(trials.excess_distance.mean(),2),"median_excess_travel_time":round(trials.excess_distance.median(),2),"realized-optimal arrivals (%)":pct(trials.realized_optimal),"on-time arrivals (%)":pct(trials.on_time_bool),"easy normative first choices (%)":pct(trials.loc[trials.difficulty.eq("easy"),"good_first_choice"]),"safe choice on mean-equivalent corridor (%)":pct(trials.safe_on_equal_mean),"trials using surveillance (%)":pct(trials.used_surveillance),"mean surveillance uses per trial":round(trials.surveillance_count.mean(),2),"mean refuel visits on fuel maps":round(trials.loc[trials.fuel_capacity.notna(),"refuel_visits"].mean(),2)}]); summary.to_csv(OUT/"overall_summary.csv",index=False)
by=(trials.groupby(["level", "difficulty","condition","objective"],dropna=False).agg(participants=("participant_id","nunique"),trials=("participant_id","size"),mean_excess_time=("excess_distance","mean"),median_excess_time=("excess_distance","median"),realized_optimal_pct=("realized_optimal",pct),on_time_pct=("on_time_bool",pct),good_first_choice_pct=("good_first_choice",pct),risky_choice_pct=("choice_class",lambda x:pct(x.eq("risky"))),safe_choice_pct=("choice_class",lambda x:pct(x.eq("safe"))),scout_choice_pct=("choice_class",lambda x:pct(x.eq("scout"))),surveillance_use_pct=("used_surveillance",pct),mean_surveillance_uses=("surveillance_count","mean"),all_surveys_relevant_pct=("all_surveys_hindsight_relevant",pct),mean_refuel_visits=("refuel_visits","mean"),mean_minimum_fuel_remaining=("minimum_fuel_remaining","mean")).reset_index()); by[["mean_excess_time","median_excess_time","mean_surveillance_uses"]]=by[["mean_excess_time","median_excess_time","mean_surveillance_uses"]].round(2); by.to_csv(OUT/"condition_objective_summary.csv",index=False)
if surveys.empty: surv_summary=pd.DataFrame([{ "surveillance_events":0}]); surv_by=pd.DataFrame()
else:
 surv_summary=pd.DataFrame([{ "surveillance_events":len(surveys),"participants_surveying":surveys.participant_id.nunique(),"surveys before first move (%)":pct(surveys.moves.eq(0)),"early surveys (%)":pct(surveys.timing_stage.eq("early")),"middle surveys (%)":pct(surveys.timing_stage.eq("middle")),"late surveys (%)":pct(surveys.timing_stage.eq("late")),"mean time to survey (s)":round(surveys.elapsed_seconds.mean(),2),"mean relative decision time":round(surveys.relative_decision_time.mean(),3),"blocked roads found (%)":pct(~surveys.surveilled_open_bool),"hindsight-relevant survey targets (%)":pct(surveys.hindsight_relevant_bool)}]); surv_by=surveys.groupby(["difficulty","condition","objective","timing_stage"],observed=False).agg(surveys=("event","size"),participants=("participant_id","nunique"),mean_elapsed_seconds=("elapsed_seconds","mean"),blocked_found_pct=("surveilled_open_bool",lambda x:pct(~x)),hindsight_relevant_target_pct=("hindsight_relevant_bool",pct)).reset_index(); surv_by["mean_elapsed_seconds"]=surv_by.mean_elapsed_seconds.round(2)
surv_summary.to_csv(OUT/"surveillance_summary.csv",index=False); surv_by.to_csv(OUT/"surveillance_by_condition_timing.csv",index=False)
pstrat=trials.groupby("participant_id").agg(completed_trials=("trial","size"),mean_excess_time=("excess_distance","mean"),on_time_pct=("on_time_bool",pct),trials_using_surveillance_pct=("used_surveillance",pct),total_surveillance_uses=("surveillance_count","sum"),relevant_target_count=("relevant_survey_count","sum"),total_refuel_visits=("refuel_visits","sum"),age_band=("age_band","first"),gender=("gender","first")).reset_index(); uses=trials.groupby("participant_id").surveillance_count.sum(); rel=trials.groupby("participant_id").relevant_survey_count.sum(); pstrat["hindsight_relevant_target_pct"]=pstrat.participant_id.map((100*rel/uses.replace(0,float("nan"))).round(1)); pstrat["mean_excess_time"]=pstrat.mean_excess_time.round(2); pstrat.to_csv(OUT/"participant_strategy_summary.csv",index=False)
write_groups(trials,"age_band","age_summary.csv"); write_groups(trials,"gender","gender_summary.csv")
report=f'''DISASTER-RELIEF ROUTE TASK: EXPLORATORY ANALYSIS\n\nCompleted participants: {trials.participant_id.nunique()}\nCompleted trials: {len(trials)}\nMean excess travel time over hindsight best feasible route (including fuel constraints where applicable): {trials.excess_distance.mean():.2f}\nRealised-optimal arrivals: {pct(trials.realized_optimal):.1f}%\nOn-time arrivals: {pct(trials.on_time_bool):.1f}%\nEasy-trial normative first choices: {pct(trials.loc[trials.difficulty.eq("easy"),"good_first_choice"]):.1f}%\nTrials using surveillance: {pct(trials.used_surveillance):.1f}%\nMean surveillance uses per trial: {trials.surveillance_count.mean():.2f}\nMean refuelling visits on fuel-constrained maps: {trials.loc[trials.fuel_capacity.notna(), "refuel_visits"].mean():.2f}\n\nFUEL-CONSTRAINED HARD MAPS\n* The final two maps impose a visible fuel-capacity constraint. Fuel is consumed one-for-one with travel time and is automatically replenished at green-tinted FUEL nodes.\n* participant_trial_data.csv reports refuel_visits and minimum_fuel_remaining. Insufficient-fuel attempts remain in the raw event log; they should be described as planning errors, not as a psychological trait.\n\nSURVEILLANCE INTERPRETATION\n* surveillance_events.csv records each use and timing. Timing is before first move / early / middle / late using the share of completed-trial decision time.\n* Hindsight-relevant target means toggling that road's realised state would change the shortest remaining route from the player's position. It is an ex-post target-relevance diagnostic, not evidence participants could know usefulness in advance.\n* Do not label individual choices as smart or stupid. Report timing, target relevance, and subsequent performance separately; this task has no formal optimal information-acquisition policy benchmark.\n* To estimate a causal effect of surveillance, randomise 0, 1, or 2 credits and record assignment; user/non-user comparisons are self-selected.\n\nFILES\nparticipant_trial_data.csv: one completed trial per row; primary modelling input.\nsurveillance_events.csv: one surveillance choice per row.\nsurveillance_summary.csv and surveillance_by_condition_timing.csv: descriptive timing and target relevance.\nparticipant_strategy_summary.csv: per-participant descriptive profile.
stranded_trials.csv: terminal stranding events, if any.\ncondition_objective_summary.csv, age_summary.csv, gender_summary.csv: trial and subgroup descriptives.\n'''; (OUT/"analysis_report.txt").write_text(report,encoding="utf-8"); print(report); print(f"Wrote analysis files to {OUT}")
